window.CODE = Object.assign(window.CODE || {}, {"ch32/cost.py":"\"\"\"Tokens -> money, and a daily token budget. Prices live in prices.json because they change.\"\"\"\nimport json\nimport time\nfrom pathlib import Path\n\nPRICES = json.loads((Path(__file__).parent / \"prices.json\").read_text())\n\n\ndef estimate_tokens(text: str) -> int:\n    \"\"\"Rough rule of thumb for English: about 4 characters per token. Used only when the provider reports no usage.\"\"\"\n    return max(1, round(len(text) / 4))\n\n\ndef cost_usd(model: str, tokens_in: int, tokens_out: int) -> float:\n    p = PRICES.get(model)\n    if p is None:\n        raise KeyError(f\"no price for {model!r}: add it to prices.json\")      # an unknown model must not look free\n    return (tokens_in * p[\"input\"] + tokens_out * p[\"output\"]) / 1_000_000\n\n\nclass DailyTokenBudget:\n    \"\"\"Stop spending when today's tokens reach the limit. Resets at the start of each day (UTC).\"\"\"\n\n    def __init__(self, limit_tokens: int, clock=time.time):\n        self.limit, self.clock, self.used = limit_tokens, clock, 0\n        self.day = self._today()\n\n    def _today(self) -> int:\n        return int(self.clock() // 86400)\n\n    def _roll(self):\n        if self._today() != self.day:\n            self.day, self.used = self._today(), 0\n\n    def allow(self, estimate: int = 0) -> bool:\n        self._roll()\n        return self.used + estimate <= self.limit\n\n    def record(self, tokens: int):\n        self._roll()\n        self.used += tokens\n\n    @property\n    def remaining(self) -> int:\n        self._roll()\n        return max(0, self.limit - self.used)\n","ch32/deploy/alerts.yml":"# Alert rules for the helpdesk. YAML-checked only; run `promtool check rules alerts.yml` before using (promtool ships with Prometheus).\ngroups:\n  - name: helpdesk\n    rules:\n      # SLO: 99% of requests end in outcome=\"ok\". Burn rate = bad share / allowed bad share (0.01).\n      - alert: HelpdeskErrorBudgetFastBurn\n        expr: |\n          (\n            sum(rate(helpdesk_requests_total{outcome!=\"ok\"}[5m])) / sum(rate(helpdesk_requests_total[5m])) / 0.01 > 14.4\n          ) and (\n            sum(rate(helpdesk_requests_total{outcome!=\"ok\"}[1h])) / sum(rate(helpdesk_requests_total[1h])) / 0.01 > 14.4\n          )\n        for: 2m\n        labels: {severity: page}\n        annotations:\n          summary: \"Helpdesk is spending its 30-day error budget about 14x too fast\"\n      - alert: HelpdeskSlowReplies\n        expr: histogram_quantile(0.95, sum(rate(helpdesk_request_seconds_bucket[10m])) by (le)) > 8\n        for: 10m\n        labels: {severity: ticket}\n        annotations:\n          summary: \"95th percentile reply time above 8 seconds\"\n      - alert: HelpdeskCostSpike\n        expr: sum(increase(helpdesk_cost_usd_total[1h])) > 5\n        labels: {severity: ticket}\n        annotations:\n          summary: \"More than $5 spent in the last hour (check for a loop or an attack)\"\n      - alert: HelpdeskModelCallsPerRequestUp\n        expr: |\n          sum(rate(helpdesk_model_calls_total[30m])) / sum(rate(helpdesk_requests_total[30m])) > 8\n        for: 15m\n        labels: {severity: ticket}\n        annotations:\n          summary: \"Average model calls per request above 8 (agent may be looping)\"\n      - alert: HelpdeskDailyBudgetLow\n        expr: helpdesk_daily_tokens_remaining < 10000\n        labels: {severity: ticket}\n        annotations:\n          summary: \"Under 10,000 tokens left in today's budget\"\n","ch32/deploy/docker-compose.yml":"# Local monitoring stack: Jaeger (traces), Prometheus (metrics), Grafana (dashboards).\n# YAML-checked only; not run here (no Docker in the build sandbox).\n#   docker compose up -d\n#   OTEL_EXPORTER_OTLP_ENDPOINT=http://localhost:4318 OFFLINE=1 python serve_metrics.py\n#   Jaeger  http://localhost:16686   Prometheus http://localhost:9090   Grafana http://localhost:3000\nservices:\n  jaeger:\n    image: jaegertracing/all-in-one:latest        # pin a version number in real use\n    environment:\n      COLLECTOR_OTLP_ENABLED: \"true\"\n    ports: [\"16686:16686\", \"4318:4318\"]           # UI, OTLP over HTTP\n  prometheus:\n    image: prom/prometheus:latest\n    volumes: [\"./prometheus.yml:/etc/prometheus/prometheus.yml:ro\", \"./alerts.yml:/etc/prometheus/alerts.yml:ro\"]\n    extra_hosts: [\"host.docker.internal:host-gateway\"]\n    ports: [\"9090:9090\"]\n  grafana:\n    image: grafana/grafana:latest\n    ports: [\"3000:3000\"]\n    depends_on: [prometheus]\n","ch32/deploy/prometheus.yml":"# Prometheus: scrape the helpdesk's /metrics every 15 seconds and load the alert rules.\n# YAML-checked only; not run against a live Prometheus here.\nglobal:\n  scrape_interval: 15s\n  evaluation_interval: 15s\nrule_files:\n  - alerts.yml\nscrape_configs:\n  - job_name: clinic-helpdesk\n    static_configs:\n      - targets: [\"host.docker.internal:8000\"]     # the helpdesk running on your machine (serve_metrics.py)\n","ch32/drift.py":"\"\"\"Has what patients ask changed? A small drift detector with a deterministic text embedding (no API needed).\n\nIn production use your real embedding model (llm.embed); the detector code is identical, only embed() changes.\n\"\"\"\nimport hashlib\nimport re\n\nimport numpy as np\n\nDIM = 256\n\n\ndef embed(text: str) -> np.ndarray:\n    \"\"\"Hashed bag-of-words: crude, but stable and offline. Same words -> same direction.\"\"\"\n    v = np.zeros(DIM)\n    for w in re.findall(r\"[a-z0-9]+\", text.lower()):\n        v[int(hashlib.md5(w.encode()).hexdigest(), 16) % DIM] += 1.0\n    n = np.linalg.norm(v)\n    return v / n if n else v\n\n\ndef _matrix(texts):\n    return np.vstack([embed(t) for t in texts])\n\n\ndef centroid_shift(baseline: list[str], recent: list[str]) -> float:\n    \"\"\"Cosine distance between the average question then and now. 0 = same topic mix, towards 1 = very different.\"\"\"\n    a, b = _matrix(baseline).mean(axis=0), _matrix(recent).mean(axis=0)\n    return float(1 - a @ b / (np.linalg.norm(a) * np.linalg.norm(b)))\n\n\ndef novelty(baseline: list[str], recent: list[str]) -> float:\n    \"\"\"Average distance from each recent question to its nearest baseline question. High = questions we have not seen.\"\"\"\n    B, R = _matrix(baseline), _matrix(recent)\n    return float(np.mean(1 - (R @ B.T).max(axis=1)))\n\n\ndef calibrate(baseline: list[str], size: int, trials: int = 300, seed: int = 0, quantile: float = 0.95) -> dict:\n    \"\"\"How much do these two numbers wobble when NOTHING has changed? Draw `size` random questions from the baseline,\n    compare them with the rest, repeat; the 95th percentile is the normal-wobble limit. Anything above it is worth a look.\"\"\"\n    rng = np.random.default_rng(seed)\n    c, n = [], []\n    for _ in range(trials):\n        idx = rng.permutation(len(baseline))\n        part, rest = [baseline[i] for i in idx[:size]], [baseline[i] for i in idx[size:]]\n        c.append(centroid_shift(rest, part))\n        n.append(novelty(rest, part))\n    return {\"centroid_limit\": float(np.quantile(c, quantile)), \"novelty_limit\": float(np.quantile(n, quantile))}\n\n\ndef check(baseline: list[str], recent: list[str], limits: dict | None = None) -> dict:\n    limits = limits or calibrate(baseline, len(recent))\n    c, n = centroid_shift(baseline, recent), novelty(baseline, recent)\n    return {\"centroid_shift\": round(c, 3), \"novelty\": round(n, 3), \"limits\": {k: round(v, 3) for k, v in limits.items()},\n            \"drift\": c > limits[\"centroid_limit\"] or n > limits[\"novelty_limit\"]}\n","ch32/metrics.py":"\"\"\"Prometheus metrics for the helpdesk. Metrics answer \"how is it doing overall?\"; traces answer \"what happened in THIS request?\".\n\nRULE: label values must come from a SMALL fixed set (outcome, model, route). Never put a patient id, a request id or free text in a label:\nevery distinct value creates a new time series, and that is how monitoring systems fall over (high cardinality).\n\"\"\"\nfrom prometheus_client import CollectorRegistry, Counter, Gauge, Histogram, generate_latest\n\nREGISTRY = CollectorRegistry()\nREQUESTS = Counter(\"helpdesk_requests_total\", \"Requests by outcome\", [\"outcome\"], registry=REGISTRY)       # ok | fallback | stopped | error\nLATENCY = Histogram(\"helpdesk_request_seconds\", \"End-to-end request time\", registry=REGISTRY,\n                    buckets=(0.5, 1, 2, 4, 8, 15, 30))\nMODEL_CALLS = Counter(\"helpdesk_model_calls_total\", \"Model calls\", [\"model\"], registry=REGISTRY)\nTOKENS = Counter(\"helpdesk_tokens_total\", \"Tokens used\", [\"direction\", \"source\"], registry=REGISTRY)         # source: reported | estimated\nCOST = Counter(\"helpdesk_cost_usd_total\", \"Estimated spend in US dollars\", registry=REGISTRY)\nFLAGS = Counter(\"helpdesk_flags_total\", \"Safety flags raised\", [\"flag\"], registry=REGISTRY)\nBUDGET_LEFT = Gauge(\"helpdesk_daily_tokens_remaining\", \"Tokens left in today's budget\", registry=REGISTRY)\n\n\ndef exposition() -> str:\n    \"\"\"What GET /metrics returns: plain text that Prometheus scrapes every 15 seconds or so.\"\"\"\n    return generate_latest(REGISTRY).decode()\n","ch32/monitored.py":"\"\"\"The Chapter 27 helpdesk with traces (OpenTelemetry), metrics (Prometheus), cost and a daily token budget switched on.\"\"\"\nimport os\nimport sys\nimport time\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch31\"))\nimport setup_helpdesk  # noqa: E402,F401  (ch31's shared set-up: path + offline model)\nimport helpdesk  # noqa: E402\nfrom helpdesk import Budget, Command, StopRun  # noqa: E402\nfrom config import FALLBACK  # noqa: E402\nfrom cost import DailyTokenBudget, cost_usd, estimate_tokens  # noqa: E402\nfrom langchain_core.callbacks import BaseCallbackHandler  # noqa: E402\nimport metrics as m  # noqa: E402\nfrom telemetry import OtelCallback, setup_tracing  # noqa: E402\n\nTRACER = setup_tracing()\nDAILY = DailyTokenBudget(int(os.getenv(\"DAILY_TOKEN_LIMIT\", \"200000\")))\nimport llm  # noqa: E402  (code-samples/llm.py, the two-provider helper)\nMODEL_NAME = \"fake-model\" if os.getenv(\"OFFLINE\") == \"1\" else llm.MODELS[llm.PROVIDER]\n\n\nclass UsageCounter(BaseCallbackHandler):\n    \"\"\"Adds up tokens for one request. Uses the provider's numbers when present, an estimate otherwise (and says which).\"\"\"\n    raise_error = False\n\n    def __init__(self):\n        self.tin = self.tout = self.calls = 0\n        self.estimated = False\n        self._in = {}\n\n    def on_chat_model_start(self, serialized, messages, *, run_id, **kw):\n        self._in[run_id] = sum(len(str(x.content)) for b in messages for x in b)\n\n    def on_llm_end(self, response, *, run_id, **kw):\n        gen = response.generations[0][0]\n        u = getattr(getattr(gen, \"message\", None), \"usage_metadata\", None) or {}\n        self.calls += 1\n        if u.get(\"input_tokens\") is not None:\n            self.tin += u[\"input_tokens\"]\n            self.tout += u.get(\"output_tokens\", 0)\n        else:\n            self.estimated = True\n            self.tin += max(1, self._in.pop(run_id, 0) // 4)\n            self.tout += estimate_tokens(str(getattr(gen, \"text\", \"\")))\n\n\n@dataclass\nclass Monitored:\n    reply: str\n    outcome: str\n    seconds: float\n    model_calls: int\n    tokens_in: int\n    tokens_out: int\n    cost: float\n    flags: list = field(default_factory=list)\n\n\ndef monitored_run(request: str, approver=lambda p: {\"approved\": True}) -> Monitored:\n    if not DAILY.allow(estimate=2000):                                   # budget check BEFORE spending anything\n        m.REQUESTS.labels(\"fallback\").inc()\n        m.BUDGET_LEFT.set(DAILY.remaining)\n        return Monitored(FALLBACK, \"fallback\", 0.0, 0, 0, 0, 0.0, [\"daily_budget_reached\"])\n    graph, usage, started = helpdesk.get_graph(), UsageCounter(), time.time()\n    config = {\"configurable\": {\"thread_id\": f\"t{time.time_ns()}\"}, \"callbacks\": [Budget(), usage, OtelCallback(TRACER)]}\n    flags, outcome = [], \"ok\"\n    with TRACER.start_as_current_span(\"helpdesk.request\") as root:       # the root span: everything else nests under it\n        try:\n            out = graph.invoke({\"request\": request}, config)\n            while out.get(\"__interrupt__\"):\n                out = graph.invoke(Command(resume=approver(out[\"__interrupt__\"][0].value)), config)\n        except StopRun as stop:\n            out, outcome = {\"reply\": FALLBACK}, \"stopped\"\n            flags.append(f\"stopped:{stop}\")\n        except Exception as e:                                           # count it, mark the span, then still answer safely\n            out, outcome = {\"reply\": FALLBACK}, \"error\"\n            root.record_exception(e)\n        reply = out.get(\"reply\", FALLBACK)\n        flags += out.get(\"flags\", [])\n        if outcome == \"ok\" and reply == FALLBACK:\n            outcome = \"fallback\"\n        seconds = time.time() - started\n        usd = cost_usd(MODEL_NAME, usage.tin, usage.tout)\n        root.set_attributes({\"helpdesk.outcome\": outcome, \"helpdesk.model_calls\": usage.calls, \"gen_ai.usage.input_tokens\": usage.tin,\n                             \"gen_ai.usage.output_tokens\": usage.tout, \"helpdesk.cost_usd\": usd, \"helpdesk.tokens_estimated\": usage.estimated})\n    src = \"estimated\" if usage.estimated else \"reported\"\n    m.REQUESTS.labels(outcome).inc()\n    m.LATENCY.observe(seconds)\n    m.MODEL_CALLS.labels(MODEL_NAME).inc(usage.calls)\n    m.TOKENS.labels(\"input\", src).inc(usage.tin)\n    m.TOKENS.labels(\"output\", src).inc(usage.tout)\n    m.COST.inc(usd)\n    for f in flags:\n        m.FLAGS.labels(f.split(\":\")[0]).inc()\n    DAILY.record(usage.tin + usage.tout)\n    m.BUDGET_LEFT.set(DAILY.remaining)\n    return Monitored(reply, outcome, round(seconds, 3), usage.calls, usage.tin, usage.tout, round(usd, 6), flags)\n","ch32/prices.json":"{\n  \"_note\": \"ILLUSTRATIVE prices in US dollars per 1 million tokens. Prices change: copy the current numbers from your provider's pricing page before you rely on any cost figure.\",\n  \"gpt-4.1-mini\": {\"input\": 0.40, \"output\": 1.60},\n  \"claude-haiku-5-5\": {\"input\": 1.00, \"output\": 5.00},\n  \"fake-model\": {\"input\": 0.40, \"output\": 1.60}\n}\n","ch32/README.md":"# Chapter 32: monitoring, cost and drift\n\n    OFFLINE=1 pytest -q                  # 11 tests\n    OFFLINE=1 python serve_metrics.py    # then open http://localhost:8000/metrics (a little traffic is generated for you)\n\nNeeds the packages in `../requirements.txt` (OpenTelemetry, prometheus_client). Prices in `prices.json` are illustrative: change them to your provider's.\n\n**Not run here:** a live Prometheus, Grafana or Jaeger (the files in `deploy/` are validated as YAML and by the tests, but no server was started), and any hosted OpenTelemetry back end.\n","ch32/sample_questions.py":"\"\"\"Synthetic City Clinic questions for the drift demo. BASELINE = the usual mix; NEW_TOPIC = a flu-shot campaign changes what people ask.\"\"\"\n_HANDWRITTEN = [\n    \"What days does Dr Khan see children?\", \"Why is there an ECG charge on my bill?\", \"What are the OPD timings?\",\n    \"Is the PMJAY scheme accepted for consumables?\", \"Can I book Dr Rao on Thursday?\", \"What are the ICU visiting hours?\",\n    \"How do I get a copy of my bill BILL-2291?\", \"Which doctor handles knee pain?\", \"What is the registration fee for OPD?\",\n    \"Does Dr Mehta see patients on Wednesday?\", \"Where do I pay the pharmacy bill?\", \"What time does the cardiology clinic open?\",\n    \"Can I change my appointment with Dr Iyer?\", \"What documents do I bring for my first visit?\", \"How long is the wait for an ECG?\",\n    \"Is there parking at the clinic?\", \"What is the fee for a paediatric consultation?\", \"Can I get my reports by email?\",\n    \"Which days is orthopaedics open?\", \"How do I cancel my booking with Dr Khan?\",\n]\nSAME_MIX = [\n    \"What are the OPD timings on Saturday?\", \"Can I see Dr Khan on Friday?\", \"How much is the ECG?\",\n    \"Where can I collect my reports?\", \"Is Dr Iyer available on Tuesday?\", \"How do I pay my bill?\",\n    \"Is PMJAY accepted at the front desk?\", \"When is the cardiology clinic open?\",\n]\nNEW_TOPIC = [\n    \"Is the flu vaccine available this week?\", \"How much does the flu vaccine cost for adults?\", \"Can children get the flu vaccine here?\",\n    \"Do I need an appointment for the flu vaccine?\", \"Is the flu vaccine free for senior citizens?\", \"Which days is the vaccine camp open?\",\n    \"Are there side effects after the flu vaccine?\", \"Can I take the flu vaccine with my diabetes tablets?\",\n]\n\n\ndef _more():\n    \"\"\"Template-made variety so the baseline is big enough (real traffic gives you hundreds of questions for free).\"\"\"\n    docs = [\"Dr Mehta\", \"Dr Rao\", \"Dr Iyer\", \"Dr Khan\"]\n    days = [\"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\"]\n    out = []\n    for i, d in enumerate(docs):\n        for j, day in enumerate(days):\n            kind = (i + j) % 4\n            out.append([f\"Is {d} available on {day}?\", f\"Can I book {d} for {day} morning?\",\n                        f\"What time does {d} start on {day}?\", f\"Can I move my {day} appointment with {d}?\"][kind])\n    for item in [\"ECG\", \"X-ray\", \"blood test\", \"consultation\", \"registration\", \"ultrasound\", \"physiotherapy\"]:\n        out += [f\"How much is the {item} fee?\", f\"Why is there a {item} charge on my bill?\"]\n    for scheme in [\"PMJAY\", \"CGHS\", \"my insurance\", \"cashless\"]:\n        out += [f\"Is {scheme} accepted here?\", f\"Which documents do I need for {scheme}?\"]\n    return out\n\n\nBASELINE = _HANDWRITTEN + _more()\n","ch32/serve_metrics.py":"\"\"\"Run the helpdesk with a live /metrics page and a little traffic, so Prometheus has something to scrape.\n\n    OFFLINE=1 python serve_metrics.py          # then open http://localhost:8000/metrics\n\"\"\"\nimport itertools\nimport time\n\nfrom prometheus_client import start_http_server\n\nimport metrics\nfrom monitored import monitored_run\nfrom sample_questions import BASELINE\n\nif __name__ == \"__main__\":\n    start_http_server(8000, registry=metrics.REGISTRY)          # GET /metrics on port 8000\n    print(\"metrics on http://localhost:8000/metrics  (Ctrl+C to stop)\")\n    for q in itertools.cycle(BASELINE[:12]):\n        monitored_run(q)\n        time.sleep(1)\n","ch32/slo.py":"\"\"\"SLIs, SLOs, error budgets and burn rates: the arithmetic behind \"are we okay?\" (pure functions, no libraries).\"\"\"\n\n\ndef error_budget(slo: float, total: int) -> float:\n    \"\"\"How many bad requests the SLO allows out of `total`. slo=0.99 over 10,000 requests -> 100 allowed bad.\"\"\"\n    return (1 - slo) * total\n\n\ndef budget_remaining(slo: float, good: int, total: int) -> float:\n    \"\"\"Share of the error budget still unspent: 1.0 = untouched, 0 = used up, negative = overspent.\"\"\"\n    allowed = error_budget(slo, total)\n    bad = total - good\n    return 1.0 if allowed == 0 and bad == 0 else (allowed - bad) / allowed if allowed else float(\"-inf\")\n\n\ndef burn_rate(slo: float, good: int, total: int) -> float:\n    \"\"\"How fast the budget is being spent. 1.0 = exactly on pace to use it all by the end of the period; 10 = ten times too fast.\"\"\"\n    if total == 0:\n        return 0.0\n    return ((total - good) / total) / (1 - slo)\n\n\ndef should_page(slo: float, fast: tuple[int, int], slow: tuple[int, int], threshold: float = 14.4) -> bool:\n    \"\"\"Multi-window alert: page only if BOTH a short window (e.g. 5 min) and a longer one (e.g. 1 hour) burn fast.\n    The short window makes the alert stop quickly once fixed; the long one stops a brief blip from waking anyone.\n    Each window is (good, total). 14.4 is the widely used 'spend 2% of a 30-day budget in an hour' threshold.\"\"\"\n    return burn_rate(slo, *fast) >= threshold and burn_rate(slo, *slow) >= threshold\n","ch32/telemetry.py":"\"\"\"OpenTelemetry (OTel) for the helpdesk: the industry-standard way to produce traces that ANY backend can show.\n\nA LangChain callback turns each model call and tool call into an OTel span. Where the spans go is configuration:\n  - nothing set            -> kept in memory (tests, and the demo below)\n  - OTEL_EXPORTER_OTLP_ENDPOINT=http://localhost:4318  -> sent to Jaeger, Grafana Tempo, Phoenix, Datadog... (untested here: needs a collector)\n\"\"\"\nimport os\n\nfrom langchain_core.callbacks import BaseCallbackHandler\nfrom opentelemetry import trace\nfrom opentelemetry.sdk.resources import Resource\nfrom opentelemetry.sdk.trace import TracerProvider\nfrom opentelemetry.sdk.trace.export import BatchSpanProcessor, SimpleSpanProcessor\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\n\n_provider = None\nMEMORY = InMemorySpanExporter()\n\n\ndef setup_tracing(service: str = \"clinic-helpdesk\"):\n    \"\"\"Call once at start-up. Safe to call twice.\"\"\"\n    global _provider\n    if _provider is None:\n        _provider = TracerProvider(resource=Resource.create({\"service.name\": service}))\n        _provider.add_span_processor(SimpleSpanProcessor(MEMORY))\n        if os.getenv(\"OTEL_EXPORTER_OTLP_ENDPOINT\"):\n            from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter\n            _provider.add_span_processor(BatchSpanProcessor(OTLPSpanExporter()))   # reads the endpoint from the environment\n    return _provider.get_tracer(\"helpdesk\")\n\n\nclass OtelCallback(BaseCallbackHandler):\n    \"\"\"Nest every model/tool call under the currently active request span.\"\"\"\n    raise_error = False\n\n    def __init__(self, tracer):\n        self.tracer, self.spans = tracer, {}\n\n    def _start(self, run_id, parent_run_id, name, attrs):\n        parent = self.spans.get(parent_run_id)\n        ctx = trace.set_span_in_context(parent) if parent is not None else None      # None -> the active request span\n        self.spans[run_id] = self.tracer.start_span(name, context=ctx, attributes=attrs)\n\n    def _end(self, run_id, error=None, attrs=None):\n        span = self.spans.pop(run_id, None)\n        if span is None:\n            return\n        for k, v in (attrs or {}).items():\n            if v is not None:\n                span.set_attribute(k, v)\n        if error:\n            span.set_status(trace.Status(trace.StatusCode.ERROR, type(error).__name__))\n            span.record_exception(error)\n        span.end()\n\n    def on_chat_model_start(self, serialized, messages, *, run_id, parent_run_id=None, metadata=None, **kw):\n        node = (metadata or {}).get(\"langgraph_node\") or \"model\"\n        chars = sum(len(str(m.content)) for batch in messages for m in batch)\n        self._start(run_id, parent_run_id, f\"chat {node}\", {\"gen_ai.operation.name\": \"chat\", \"helpdesk.node\": node, \"helpdesk.input_chars\": chars})\n\n    def on_llm_end(self, response, *, run_id, **kw):\n        gen = response.generations[0][0]\n        usage = getattr(getattr(gen, \"message\", None), \"usage_metadata\", None) or {}\n        self._end(run_id, attrs={\"gen_ai.usage.input_tokens\": usage.get(\"input_tokens\"), \"gen_ai.usage.output_tokens\": usage.get(\"output_tokens\"),\n                                 \"helpdesk.output_chars\": len(str(getattr(gen, \"text\", \"\")))})\n\n    def on_llm_error(self, error, *, run_id, **kw):\n        self._end(run_id, error=error)\n\n    def on_tool_start(self, serialized, input_str, *, run_id, parent_run_id=None, **kw):\n        name = (serialized or {}).get(\"name\", \"tool\")\n        self._start(run_id, parent_run_id, f\"tool {name}\", {\"gen_ai.operation.name\": \"execute_tool\", \"gen_ai.tool.name\": name})\n\n    def on_tool_end(self, output, *, run_id, **kw):\n        self._end(run_id)\n\n    def on_tool_error(self, error, *, run_id, **kw):\n        self._end(run_id, error=error)\n","ch32/test_ch32.py":"\"\"\"Offline tests for Chapter 32.  OFFLINE=1 pytest -q\"\"\"\nimport os\nimport re\nimport urllib.request\nfrom pathlib import Path\n\nos.environ[\"OFFLINE\"] = \"1\"\nimport pytest  # noqa: E402\nimport yaml  # noqa: E402\nfrom prometheus_client import start_http_server  # noqa: E402\nfrom prometheus_client.parser import text_string_to_metric_families  # noqa: E402\n\nimport cost  # noqa: E402\nimport drift  # noqa: E402\nimport metrics  # noqa: E402\nimport slo  # noqa: E402\nfrom monitored import monitored_run  # noqa: E402\nfrom sample_questions import BASELINE, NEW_TOPIC, SAME_MIX  # noqa: E402\nfrom telemetry import MEMORY  # noqa: E402\n\n\ndef test_cost_arithmetic_and_unknown_model():\n    assert cost.cost_usd(\"gpt-4.1-mini\", 1_000_000, 1_000_000) == pytest.approx(0.40 + 1.60)\n    with pytest.raises(KeyError):\n        cost.cost_usd(\"mystery-model\", 10, 10)\n\n\ndef test_daily_budget_blocks_and_resets():\n    now = [0.0]\n    b = cost.DailyTokenBudget(1000, clock=lambda: now[0])\n    assert b.allow(500)\n    b.record(900)\n    assert not b.allow(500) and b.remaining == 100\n    now[0] += 86400                                  # next day\n    assert b.allow(500) and b.remaining == 1000\n\n\ndef test_slo_math():\n    assert slo.error_budget(0.99, 10_000) == pytest.approx(100)\n    assert slo.budget_remaining(0.99, good=9_950, total=10_000) == pytest.approx(0.5)\n    assert slo.burn_rate(0.99, good=9_900, total=10_000) == pytest.approx(1.0)\n    assert slo.burn_rate(0.99, good=8_560, total=10_000) == pytest.approx(14.4)\n    assert slo.budget_remaining(0.99, good=9_800, total=10_000) < 0           # overspent\n\n\ndef test_multiwindow_alert_ignores_a_short_blip():\n    assert slo.should_page(0.99, fast=(80, 100), slow=(7_000, 7_100)) is False  # 5-min window bad, hour fine: a blip\n    assert slo.should_page(0.99, fast=(80, 100), slow=(6_000, 8_000)) is True   # both windows bad (25% bad = burn rate 25)\n\n\ndef test_run_creates_nested_spans_with_attributes():\n    MEMORY.clear()\n    r = monitored_run(\"Why is there an ECG charge on BILL-2291?\")\n    spans = MEMORY.get_finished_spans()\n    root = [s for s in spans if s.name == \"helpdesk.request\"][0]\n    kids = [s for s in spans if s.parent is not None and s.parent.span_id == root.context.span_id]\n    assert len(kids) == 5 and any(s.name == \"tool get_bill\" for s in kids)\n    assert root.attributes[\"helpdesk.outcome\"] == \"ok\" and root.attributes[\"helpdesk.cost_usd\"] > 0\n    assert r.reply.startswith(\"BILL-2291\")\n\n\ndef test_no_patient_text_in_spans():\n    MEMORY.clear()\n    monitored_run(\"Why is there an ECG charge on BILL-2291?\")\n    blob = \" \".join(str(dict(s.attributes)) for s in MEMORY.get_finished_spans())\n    assert \"BILL-2291\" not in blob and \"ECG\" not in blob\n\n\ndef test_metrics_endpoint_serves_parseable_text():\n    monitored_run(\"What are the OPD timings?\")\n    server, _ = start_http_server(0, registry=metrics.REGISTRY)         # port 0 = pick a free port\n    port = server.server_address[1]\n    body = urllib.request.urlopen(f\"http://127.0.0.1:{port}/metrics\").read().decode()\n    server.shutdown()\n    fams = {f.name: f for f in text_string_to_metric_families(body)}\n    assert \"helpdesk_requests\" in fams and \"helpdesk_request_seconds\" in fams\n    total = sum(s.value for s in fams[\"helpdesk_requests\"].samples if s.name.endswith(\"_total\"))\n    assert total >= 1\n\n\ndef test_emergency_is_counted_as_a_flag():\n    before = metrics.exposition()\n    r = monitored_run(\"I have severe chest pain\")\n    assert \"108\" in r.reply\n    assert metrics.exposition() != before\n\n\ndef test_daily_budget_exhausted_falls_back_without_calling_the_model():\n    import monitored\n    saved = monitored.DAILY\n    monitored.DAILY = cost.DailyTokenBudget(10)\n    try:\n        r = monitored.monitored_run(\"What are the OPD timings?\")\n        assert r.outcome == \"fallback\" and r.model_calls == 0 and \"daily_budget_reached\" in r.flags\n    finally:\n        monitored.DAILY = saved\n\n\ndef test_drift_detects_new_topic_not_same_mix():\n    assert drift.check(BASELINE, SAME_MIX)[\"drift\"] is False\n    assert drift.check(BASELINE, NEW_TOPIC)[\"drift\"] is True\n\n\ndef test_deploy_yaml_is_valid_and_alert_names_match_metrics():\n    here = Path(__file__).parent / \"deploy\"\n    for f in [\"prometheus.yml\", \"alerts.yml\", \"docker-compose.yml\"]:\n        assert yaml.safe_load((here / f).read_text())\n    rules = yaml.safe_load((here / \"alerts.yml\").read_text())[\"groups\"][0][\"rules\"]\n    exposed = metrics.exposition()\n    for r in rules:\n        for name in re.findall(r\"helpdesk_[a-z_]+\", r[\"expr\"]):\n            base = re.sub(r\"_(bucket|total)$\", \"\", name)\n            assert base in exposed, f\"{r['alert']} uses {name}, which the app never exposes\"\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
